insert into public.plan_items (code, grp, screen, title, detail, price, sort) values
  ('FND-01', 'foundation', null, 'lemlist API integration', 'Connects the portal to lemlist: campaigns, 3-step WhatsApp sequences, sending numbers, schedules, leads, stats, inbox and unsubscribes. Includes a job queue so the shared limit of 20 requests every 2 seconds is never hit.', 38250, 1),
  ('FND-02', 'foundation', null, 'Login, user accounts and permission control', 'Secure personal logins, invite emails, and the four roles (Main Admin, Branch Owner, Agent, Support), so each person only sees their own campaigns, branches or numbers.', 23900, 2),
  ('FND-03', 'foundation', null, 'Real-time replies and data sync', 'lemlist webhooks for new replies, plus the portal’s own database that caches stats and conversations, so screens load fast for everyone.', 11450, 3),
  ('FND-04', 'foundation', null, 'AI service setup', 'The AI behind message drafting, reply scoring and opt-out detection, with safeguards and English-only prompts.', 14350, 4),
  ('FND-05', 'foundation', null, 'Hosting, security, backups and audit trail', 'Cloud hosting, encrypted data, daily backups, and the logging that every audit entry relies on.', 9550, 5),
  ('FND-06', 'foundation', null, 'Testing, training and go-live', 'End-to-end testing with real numbers, a training session for agents and managers, and go-live support.', 23900, 6),
  ('AGT-01', 'agent', 'wizard', 'Start a new campaign from a step-by-step wizard', 'so that I can launch without knowing lemlist. Progress is saved as a draft at every step.', 3800, 7),
  ('AGT-02', 'agent', 'wizard', 'Upload a CSV of leads and match its columns', 'so that my list loads correctly. Template CSV to download. Numbers changed to +27 format.', 4800, 8),
  ('AGT-03', 'agent', 'wizard', 'See an upload summary before leads are added', 'so that I know what was accepted and why others weren’t. Added, invalid number, duplicate, on Do Not Contact, owned by another agent.', 3800, 9),
  ('AGT-04', 'agent', 'wizard', 'Describe what I’m after and get an AI-drafted 3-message sequence', 'so that I start from good copy, not a blank page. Inputs: goal, audience, offer, tone.', 5750, 10),
  ('AGT-05', 'agent', 'wizard', 'See best-practice tips beside each message', 'so that my messages get replies and my number stays safe. Short, personal, one question, no links in message 1.', 1900, 11),
  ('AGT-06', 'agent', 'wizard', 'Edit, rewrite or write any message myself, using lead fields', 'so that the copy sounds like me. Live WhatsApp-style preview with a sample lead.', 3800, 12),
  ('AGT-07', 'agent', 'wizard', 'Set the delays and the sending days and hours', 'so that messages arrive at sensible times. Starts on the company default: weekdays 07:30–18:00, South Africa time.', 2850, 13),
  ('AGT-08', 'agent', 'wizard', 'Review everything and launch', 'so that nothing goes out by mistake. Launch is blocked if my number is disconnected.', 2400, 14),
  ('AGT-09', 'agent', 'campaign', 'Pause, resume or stop a running campaign', 'so that I can react if something is wrong', 1450, 15),
  ('AGT-10', 'agent', 'campaign', 'Add more leads to a running campaign', 'so that I can top up a campaign that’s working. Same checks as a new upload.', 2400, 16),
  ('AGT-11', 'agent', 'campaign', 'Duplicate a past campaign', 'so that I can reuse a sequence that worked. Leads are not copied.', 1450, 17),
  ('AGT-12', 'agent', 'campaigns', 'See my campaigns with status and headline numbers', 'so that I know where things stand at a glance. Contacted, delivered, replied, reply rate, hot leads.', 2400, 18),
  ('AGT-13', 'agent', 'campaign', 'Open a campaign and see each lead’s progress', 'so that I know who is at which message. Queued, sent, delivered, read, replied, failed.', 2850, 19),
  ('AGT-14', 'agent', 'inbox', 'See all my WhatsApp conversations in one inbox', 'so that I can review replies in one place. Read-only. I reply from my phone.', 4800, 20),
  ('AGT-15', 'agent', 'home', 'See my number’s health and connection status', 'so that I know when to call support. A banner appears when it disconnects.', 950, 21),
  ('AGT-16', 'agent', 'inbox', 'Add a contact to Do Not Contact from a conversation', 'so that someone who says stop is never messaged again. Reason captured. Removed from all running campaigns.', 1900, 22),
  ('AGT-17', 'agent', 'inbox', 'Have every reply scored by AI with a short reason', 'so that I can focus on the most interested people. Score 0–100 plus a one-line reason.', 4800, 23),
  ('AGT-18', 'agent', 'hot', 'Have high scorers moved to Hot Leads automatically', 'so that my best leads are in one place. Threshold 70 by default, set by the Admin.', 2400, 24),
  ('AGT-19', 'agent', 'hot', 'Override the AI and move a lead in or out of Hot Leads', 'so that I stay in control of the judgement. Every override is logged.', 1900, 25),
  ('AGT-20', 'agent', 'hot', 'Export my hot leads, or all my leads, to Excel', 'so that I can load them into the CRM. Tracks which leads were already exported.', 3350, 26),
  ('AGT-21', 'agent', 'dates', 'Set a follow-up date and note on a contact', 'so that I call back at exactly the right time. From a conversation, a lead row or this page. Reminder in the portal and by email on the day.', 2500, 27),
  ('AGT-22', 'agent', 'dates', 'Save a contact’s birthday and other key dates, like a lease ending or a home anniversary', 'so that I can get in touch at moments that matter to them. Birthdays and anniversaries repeat every year.', 2000, 28),
  ('AGT-23', 'agent', 'dates', 'See everything that’s due: overdue, today and coming up', 'so that nothing slips through the cracks. Mark as done or snooze. Due items also show on Home.', 2500, 29),
  ('AGT-24', 'agent', 'dates', 'Get an AI-suggested message for a birthday, anniversary or follow-up', 'so that reaching out takes seconds. I copy it and send it from WhatsApp on my phone.', 2500, 30),
  ('ADM-01', 'admin', 'team', 'Create, rename and archive branches', 'so that the structure matches Blue PROP’s offices. Archiving a branch keeps its campaigns and history.', 1900, 31),
  ('ADM-02', 'admin', 'team', 'Invite people by email and give them a role', 'so that everyone has their own login, not a shared one. Invite link expires. One role per person.', 2850, 32),
  ('ADM-03', 'admin', 'team', 'Put each agent in one branch, and Branch Owners over one or more', 'so that what people see follows the org chart. An agent can only ever hold one branch.', 1900, 33),
  ('ADM-04', 'admin', 'team', 'Link an agent to a lemlist user and a WhatsApp number', 'so that their campaigns always send from their own number. Only unassigned numbers are offered. Max 5 numbers per lemlist user.', 2850, 34),
  ('ADM-05', 'admin', 'team', 'Deactivate an agent and reassign or close their running campaigns', 'so that a leaver’s number stops sending. Deactivating pauses their running campaigns.', 2850, 35),
  ('ADM-06', 'admin', 'campaigns', 'See every campaign across all branches, with filters', 'so that I can oversee the whole operation. Filter by branch, agent, status and date.', 2400, 36),
  ('ADM-07', 'admin', 'reports', 'See a company-wide dashboard of results', 'so that I know if WhatsApp outreach is working. Unique leads contacted, replies, reply rate and hot leads.', 4800, 37),
  ('ADM-08', 'admin', 'numbers', 'See the health and connection status of every number', 'so that disconnected numbers get fixed fast. Alert when a number disconnects.', 1450, 38),
  ('ADM-09', 'admin', 'campaign', 'Export leads from any campaign to Excel', 'so that results go into the CRM. Same export format as agents.', 1450, 39),
  ('ADM-10', 'admin', 'dnc', 'Add, bulk upload, search and remove Do Not Contact entries', 'so that we meet our opt-out obligations. Every change is logged with who and when.', 3800, 40),
  ('ADM-11', 'admin', 'rules', 'Set the Shotgun list cooldown', 'so that a contact is approached again only after the agreed time. Default 3 months.', 950, 41),
  ('ADM-12', 'admin', 'shotgun', 'See and resolve Shotgun list entries', 'so that contested contacts are handled fairly. Shows both agents and dates.', 2850, 42),
  ('ADM-13', 'admin', 'audit', 'See an audit log of key actions', 'so that disputes and compliance questions can be answered. Campaign starts, exports, Do Not Contact and people changes.', 2400, 43),
  ('BRO-01', 'owner', 'reports', 'See a dashboard for my branches over a date range', 'so that I know how my branches are doing. Default last 30 days. Switch branches or see them combined.', 5750, 44),
  ('BRO-02', 'owner', 'reports', 'See each agent’s numbers side by side', 'so that I can spot who needs help. Same measures per agent, sortable.', 2850, 45),
  ('BRO-03', 'owner', 'campaigns', 'See all campaigns in my branches with status and results', 'so that I know what’s running. Read-only. Filter by branch, agent and status.', 1450, 46),
  ('BRO-04', 'owner', 'campaign', 'Open any campaign and see its messages, leads and conversations', 'so that I can coach agents on copy and follow-up. Read-only.', 1900, 47),
  ('BRO-05', 'owner', 'numbers', 'See the health of every number in my branches', 'so that problems are flagged before campaigns stall. Alert when a number drops or a campaign is blocked.', 1450, 48),
  ('BRO-06', 'owner', 'hot', 'See my branches’ hot leads', 'so that I know which opportunities are live. Read-only.', 950, 49),
  ('BRO-07', 'owner', 'dnc', 'Remove a contact from Do Not Contact, with a reason', 'so that mistaken entries can be corrected. Reason required. Logged.', 1450, 50),
  ('BRO-08', 'owner', 'hot', 'Export leads or hot leads from my branches to Excel', 'so that results go into the CRM. Same export format as agents.', 1450, 51),
  ('BRO-09', 'owner', 'dates', 'See my agents’ upcoming and overdue follow-ups', 'so that I can make sure promised call-backs happen. Read-only. Overdue items come first.', 1500, 52),
  ('SUP-01', 'support', 'numbers', 'See every number with its lemlist user, agent and status', 'so that I know where to act. Refreshed from lemlist every few minutes.', 2400, 53),
  ('SUP-02', 'support', 'numbers', 'Be alerted when a number disconnects, is linked elsewhere or misses a licence', 'so that I can reconnect it before campaigns stall. Email or WhatsApp alert to Support.', 2850, 54),
  ('SUP-03', 'support', 'numbers', 'See how many free WhatsApp slots each lemlist user has', 'so that I know when to buy another licence. Max 5 numbers per lemlist user.', 1450, 55),
  ('SUP-04', 'support', 'numbers', 'Record a reconnection in the portal', 'so that Admins can see the issue was handled. Note plus timestamp on the number.', 1450, 56)
